def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # Enclosed blank space identifies a frame; frames rise, other
            # shapes fall. Flood blank cells within the object's bounding box.
            q=[]; outside=set()
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if y in (r0,r1) or x in (c0,c1):
                        if grid[y][x]==0 and (y,x) not in outside:
                            outside.add((y,x)); q.append((y,x))
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if r0<=ny<=r1 and c0<=nx<=c1 and grid[ny][nx]==0 and (ny,nx) not in outside:
                        outside.add((ny,nx)); q.append((ny,nx))
            has_hole=any(grid[y][x]==0 and (y,x) not in outside
                         for y in range(r0,r1+1) for x in range(c0,c1+1))
            objects.append({'color':color,'cells':cells,'r0':r0,'r1':r1,
                            'top':has_hole,'dr':0})

    # Each class moves toward its own edge; objects settle against previously
    # settled objects in their original vertical order.
    for upward in (True,False):
        group=[o for o in objects if o['top']==upward]
        group.sort(key=lambda o: (o['r0'] if upward else -o['r1']))
        settled=[]
        for o in group:
            step=-1 if upward else 1
            while True:
                shift=o['dr']+step
                moved={(r+shift,c) for r,c in o['cells']}
                if any(not (0<=r<h and 0<=c<w) for r,c in moved):
                    break
                if any(moved & prev for prev in settled):
                    break
                o['dr']=shift
            settled.append({(r+o['dr'],c) for r,c in o['cells']})

    out=[[0]*w for _ in range(h)]
    for o in objects:
        for r,c in o['cells']:
            out[r+o['dr']][c]=o['color']
    return out
